#include "Halide.h"

// include common definitions (e.g., DATA_TYPE, M, N)
#include "defines.hpp"

// include benchmark-specific definitions
#include "trmm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Array initialization, translated to Halide.
static
void init_array(int m, int n,
                num_t *alpha,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B) {
    // Set scalar alpha
    *alpha = (num_t)1.5;

    // Vars for indexing
    Var i("i"), j("j");

    // Funcs for initializing A and B
    Func init_A("init_A"), init_B("init_B");

    // Treat m and n as Halide Exprs
    Expr m_expr = Expr(m);
    Expr n_expr = Expr(n);

    // A is MxM, lower triangular with 1s on the diagonal:
    // for each row i:
    //   for j < i:  A[i][j] = ((i + j) % m) / m
    //   j == i:     A[i][i] = 1.0
    //   j > i:      A[i][j] = 0.0
    //
    // In Halide, Buffers are indexed as (x, y) = (column, row),
    // so A(i_c, i_r) = A[j][i] in C. We use (j, i) as (x, y).
    Expr a_num = (i + j) % m_expr;
    init_A(j, i) = select(j < i,
                          cast<num_t>(a_num) / cast<num_t>(m_expr),
                          select(j == i,
                                 cast<num_t>(Expr(1)),
                                 cast<num_t>(Expr(0))));

    // B is MxN:
    //   B[i][j] = ((n + (i - j)) % n) / n
    //
    // Again, B(x, y) = B[j][i] in C, so we use (j, i).
    Expr b_num = (n_expr + (i - j)) % n_expr;
    init_B(j, i) = cast<num_t>(b_num) / cast<num_t>(n_expr);

    // Realize initializations into the given Buffers.
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size
    int m = M;
    int n = N;

    // Scalars and arrays
    num_t alpha;

    // Map C arrays:
    //   A[M][M] -> Buffer A(m_cols, m_rows) = (M, M)
    //   B[M][N] -> Buffer B_in(n_cols, m_rows) = (N, M)
    Halide::Buffer<num_t, 2> A(m, m);
    Halide::Buffer<num_t, 2> B_in(n, m);
    Halide::Buffer<num_t, 2> B_out(n, m);  // output buffer

    // Initialize data
    init_array(m, n, &alpha, A, B_in);

    // ImageParams for the kernel
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    A_param.set(A);
    B_param.set(B_in);  // input B; B_out is the output

    // Vars and reduction domain
    Var j("j"), i("i");        // j = column, i = row
    RDom r(0, m, "r");         // corresponds to k in the C code

    // Define the Halide Func that implements TRMM
    //
    // Original C kernel:
    //
    // for (i = 0; i < M; i++)
    //   for (j = 0; j < N; j++) {
    //     for (k = i+1; k < M; k++)
    //       B[i][j] += A[k][i] * B[k][j];
    //     B[i][j] = alpha * B[i][j];
    //   }
    //
    // In terms of a pure functional definition (with B_in as input, B_out as output):
    //
    // B_out[i][j] = alpha * ( B_in[i][j] +
    //                         sum_{k = i+1..M-1} A[k][i] * B_in[k][j] )
    //
    // Mapping to Halide index order: B_out(j, i), B_in(j, i), A(i_col, k_row) = A[k][i].
    Func trmm("trmm");

    // Start with the original B
    trmm(j, i) = B_param(j, i);

    // Add the sum for k > i; we use a full 0..m-1 RDom with a predicate.
    trmm(j, i) += select(r > i,
                         A_param(i, r) * B_param(j, r),
                         0);

    // Finally, scale by alpha
    trmm(j, i) = trmm(j, i) * Expr(alpha);

    // JIT-compile the kernel
    trmm.compile_jit();

    // Measure execution time
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel
    trmm.realize(B_out);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print results (similar to PolyBench's print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i_row = 0; i_row < m; i_row++) {
            for (int j_col = 0; j_col < n; j_col++) {
                // B_out(j, i) corresponds to B[i][j] in the original C code
                std::cerr << B_out(j_col, i_row) << '\n';
            }
        }
    }

    // Print timing in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
