#include "defines.hpp"

// include benchmark-specific definitions
#include "trmm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize A (MxM) and B (MxN) with the same values as the original C code.
 *
 * C layout:
 *   A[i][j]  : i in [0, m), j in [0, m)
 *   B[i][j]  : i in [0, m), j in [0, n)
 *
 * Halide layout:
 *   A(x, y)  : x = column = j, y = row = i  -> A(j, i)
 *   B(x, y)  : x = column = j, y = row = i  -> B(j, i)
 */
static void init_array(int m, int n,
                       num_t *alpha,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {
    *alpha = (num_t)1.5;

    Var i("i"), j("j");
    Func init_A("init_A"), init_B("init_B");

    // A is unit lower-triangular in the original code:
    // for (i)
    //   for (j < i)  A[i][j] = ((i + j) % m) / m;
    //   A[i][i] = 1.0;
    //
    // We define A over the full domain, and match the initialized values
    // exactly where they are used. Values above the diagonal are set to 0.
    init_A(j, i) =
        select(i > j,
               // Strictly lower triangular part
               cast<num_t>((i + j) % m) / cast<int>(m),
               // Diagonal is 1, entries above diagonal are 0 (unused in kernel)
               select(i == j,
                      cast<num_t>(1),
                      cast<num_t>(0)));

    // B initialization in C:
    // B[i][j] = ((n + (i - j)) % n) / n;
    init_B(j, i) =
        cast<num_t>((n + (i - j)) % n) / cast<int>(n);

    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size
    int m = M;
    int n = N;

    // Scalars and buffers
    num_t alpha;
    // C arrays: A[M][M], B[M][N]
    // Halide Buffers: A(m, m) with A(j, i) == A[i][j]
    //                 B(n, m) with B(j, i) == B[i][j]
    Halide::Buffer<num_t, 2> A(m, m);
    Halide::Buffer<num_t, 2> B(n, m);

    // ImageParams corresponding to A and B
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Initialize data
    init_array(m, n, &alpha, A, B);

    // Bind buffers to ImageParams
    A_param.set(A);
    B_param.set(B);

    // -----------------------------
    // Halide TRMM kernel:
    //
    // Original C kernel:
    // for (i = 0; i < M; i++)
    //   for (j = 0; j < N; j++) {
    //     for (k = i+1; k < M; k++)
    //       B[i][j] += A[k][i] * B[k][j];
    //     B[i][j] = alpha * B[i][j];
    //   }
    //
    // This computes:
    //   B_out(i,j) = alpha * ( B_in(i,j)
    //                          + sum_{k=i+1}^{M-1} A[k][i] * B_in(k,j) )
    //
    // Note that all uses of B[k][j] read the original B (k > i),
    // and each B[i][j] is written only once, so we can express this
    // as a pure functional expression over the original A and B.
    // -----------------------------

    Var i("i"), j("j");
    // k indexes rows of A and B; extent is m
    RDom k(0, A.dim(0).extent(), "k");

    Func trmm("trmm");

    Expr alpha_expr = cast<num_t>(alpha);
    Expr zero = cast<num_t>(0);

    // A_param(i,k) corresponds to A[k][i]
    // B_param(j,k) corresponds to B[k][j]
    Expr accum =
        sum(select(k > i,
                   A_param(i, k) * B_param(j, k),
                   zero));

    // B_param(j,i) corresponds to original B[i][j]
    trmm(j, i) = alpha_expr * (B_param(j, i) + accum);

    // Simple schedule: iterate rows (i) outer, columns (j) inner.
    trmm.reorder(j, i);

    // Compile JIT outside the timing region
    trmm.compile_jit();

    auto start = std::chrono::high_resolution_clock::now();

    // Realize the result back into B (in-place update w.r.t. original C code)
    trmm.realize(B);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print output (mainly for debugging, matches gemm.cpp style)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // B(j, i) corresponds to B[i][j]
                std::cerr << B(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
