#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "trmm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;


/**
 * Initialize arrays A (MxM) and B (MxN) and scalar alpha.
 *
 * C version:
 *   *alpha = 1.5;
 *   for (i = 0; i < m; i++) {
 *     for (j = 0; j < i; j++)
 *       A[i][j] = ((i + j) % m) / m;
 *     A[i][i] = 1.0;
 *     for (j = 0; j < n; j++)
 *       B[i][j] = ((n + (i - j)) % n) / n;
 *   }
 *
 * We model A[i][j] as A_buf(j, i) and B[i][j] as B_buf(j, i) in Halide,
 * so dimension 0 is the column (j) and dimension 1 is the row (i),
 * matching the style used in gemm.cpp.
 */
static void init_array(int m, int n,
                       num_t *alpha,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {
    *alpha = (num_t)1.5;

    Var i("i"), j("j");
    Func init_A("init_A"), init_B("init_B");

    // Lower-triangular A with unit diagonal; upper part is set to 0.
    // A[i][j] -> init_A(j, i)
    Expr a_val = cast<num_t> ((i + j) % m) / cast<int>(m);

    init_A(j, i) = select(j < i,
                          a_val,
                          select(j == i,
                                 cast<num_t>(1.0),
                                 cast<num_t>(0.0)));

    // Full matrix B.
    // B[i][j] -> init_B(j, i)
    init_B(j, i) = cast<num_t>((n + (i - j)) % n) / cast<int>(n);

    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int m = M;
    int n = N;

    // Data.
    num_t alpha;
    // A: M x M  => Buffer(m_cols, m_rows) = (m, m)
    Halide::Buffer<num_t, 2> A(m, m);
    // B: M x N  => Buffer(n_cols, m_rows) = (n, m)
    Halide::Buffer<num_t, 2> B(n, m);

    // Initialize data.
    init_array(m, n, &alpha, A, B);

    // ImageParams corresponding to A and B.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Set ImageParams from Buffers.
    A_param.set(A);
    B_param.set(B);

    // Scalar parameter alpha.
    Param<num_t> alpha_param("alpha_param");
    alpha_param.set(alpha);

    // Vars and RDom.
    Var i("i"), j("j");
    // k runs over rows of A/B: 0 .. m-1
    RDom k(0, A.dim(1).extent(), "k");

    Func trmm("trmm");

    // Pure definition: start from original B.
    // B[i][j] in C is B_param(j, i) in Halide.
    trmm(j, i) = B_param(j, i);

    // First update: accumulate sum over k > i
    // B[i][j] += A[k][i] * B[k][j]
    // A[k][i] -> A_param(i, k)
    // B[k][j] -> B_param(j, k)
    //
    // Use an RDom with a predicate to enforce k > i.
    k.where(k > i);
    trmm(j, i) += A_param(i, k) * B_param(j, k);

    // Second update: scale by alpha
    // B[i][j] = alpha * B[i][j]
    trmm(j, i) = alpha_param * trmm(j, i);

    // Schedule:
    // We want to mimic the original traversal:
    // for (i = 0; i < m; i++)
    //   for (j = 0; j < n; j++) {
    //     for (k = i+1; k < m; k++)
    //       ...
    //   }
    //
    // Buffer layout is B(j, i), so dimension 1 (i) is outer, 0 (j) is inner.

    // Compute the result at root.
    trmm.compute_root();

    // Pure definition: i outer, j inner (default for (j, i), but be explicit).
    trmm.reorder(j, i);

    // First update (reduction): i outer, j middle, k inner.
    trmm.update(0).reorder(k, j, i);

    // Second update (scaling): i outer, j inner.
    trmm.update(1).reorder(j, i);

    // Compile the kernel to machine code.
    trmm.compile_jit();

    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel; write back into B.
    trmm.realize(B);

    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result to stderr, similar to print_array().
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C's B[ii][jj] corresponds to B(jj, ii)
                std::cerr << B(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
