    init_B(j, i) = cast<num_t>((n + (i - j)) % n) / cast<int>(n);

    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size
    int m = M;
    int n = N;

    // Scalars and matrices
    num_t alpha;
    // A is MxM  -> Buffer(m_cols, m_rows) = (m, m)
    Halide::Buffer<num_t, 2> A(m, m);
    // B is MxN  -> Buffer(n_cols, m_rows) = (n, m)
    Halide::Buffer<num_t, 2> B_in(n, m);
    Halide::Buffer<num_t, 2> B_out(n, m);

    // Initialize data
    init_array(m, n, &alpha, A, B_in);

    // Image parameters for the kernel
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Halide vars and RDom
    Var i("i"), j("j");
    RDom k(0, m, "k");

    // Define the TRMM kernel in Halide.
    //
    // Original C kernel:
    //
    // for (i = 0; i < m; i++)
    //   for (j = 0; j < n; j++) {
    //     for (k = i+1; k < m; k++)
    //       B[i][j] += A[k][i] * B[k][j];
    //     B[i][j] = alpha * B[i][j];
    //   }
    //
    // Because B[k][j] is only read for k > i, and B[k][j] is written
    // only when i == k, all reads see the original (unupdated) B.
    // So the result is:
    //   B_out[i][j] = alpha * ( B_in[i][j] + sum_{k=i+1..m-1} A[k][i] * B_in[k][j] )
    //
    // Mapping to Halide:
    //   A[k][i] -> A_param(i, k)
    //   B[k][j] -> B_param(j, k)
    //   B[i][j] -> B_param(j, i)
    //
    // We implement this as a reduction over k with a triangular mask,
    // then a separate scaling update by alpha.

    Func trmm("trmm");

    // Base value: B_in(i, j)
    trmm(j, i) = B_param(j, i);

    // Accumulate contributions from k in [0, m),
    // but only for k > i (others contribute 0).
    trmm(j, i) += select(k > i,
                         A_param(i, k) * B_param(j, k),
                         cast<num_t>(0));

    // Final scaling by alpha: trmm(j, i) = alpha * trmm(j, i)
    trmm(j, i) = trmm(j, i) * Expr(alpha);

    // Schedule: order loops to favor contiguous access in j (x) dimension.
    trmm.reorder(j, i);
    trmm.update(0).reorder(j, k, i);  // reduction update (the "+=")
    trmm.update(1).reorder(j, i);     // scaling update

    // Bind ImageParams to Buffers
    A_param.set(A);
    B_param.set(B_in);

    // Compile the kernel to machine code
    trmm.compile_jit();

    // Run the kernel and measure time
    auto start = std::chrono::high_resolution_clock::now();

    trmm.realize(B_out);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results if desired (mirrors the gemm.cpp example style)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // B_out(j, i) corresponds to B[i][j]
                std::cerr << B_out(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
